    fn bezier_warp_op(graph: &EffectRenderGraph) -> Option<crate::BezierWarpGrade> {
        graph.nodes.iter().find_map(|node| match &node.kind {
            EffectGraphNodeKind::UnaryEffect {
                op: EffectRenderOp::BezierWarp { grade }, ..
            } => Some(*grade),
            _ => None,
        })
    }

