    fn offset_op(graph: &EffectRenderGraph) -> Option<crate::OffsetGrade> {
        graph.nodes.iter().find_map(|node| match &node.kind {
            EffectGraphNodeKind::UnaryEffect { op: EffectRenderOp::Offset { grade }, .. } => {
                Some(*grade)
            }
            _ => None,
        })
    }

