    fn project(matrix: &[f64; 9], x: f64, y: f64) -> [f64; 2] {
        let third = matrix[6] * x + matrix[7] * y + matrix[8];
        [
            (matrix[0] * x + matrix[1] * y + matrix[2]) / third,
            (matrix[3] * x + matrix[4] * y + matrix[5]) / third,
        ]
    }

